<script setup>
import { computed, reactive, ref, watch } from 'vue';
import MButton from '../../../components/mds/MButton.vue'; import MDialog from '../../../components/mds/MDialog.vue'; import MInput from '../../../components/mds/MInput.vue'; import MMobileTopBar from '../../../components/mds/MMobileTopBar.vue'; import MSelect from '../../../components/mds/MSelect.vue'; import MTextarea from '../../../components/mds/MTextarea.vue';
import { EVENT_COST_CATEGORIES, toEventCostDraft, toEventCostPayload } from '../domain/event-cost-write.mjs';
const props = defineProps({ record: { type: Object, default: () => ({}) }, category: String, editing: Boolean, saving: Boolean, error: String, suppliers: { type: Array, default: () => [] }, safeAreaStyle: Object }); const emit = defineEmits(['cancel', 'save']); const draft = reactive(toEventCostDraft(props.record, props.category)); const localError = ref(''); const discard = ref(false); const title = computed(() => `${props.editing ? 'Sửa' : 'Thêm'} chi phí ${EVENT_COST_CATEGORIES.find((item) => item.value === draft.category)?.label || ''}`); const supplierOptions = computed(() => [{ value: '', label: 'Không chọn nhà cung cấp' }, ...props.suppliers.map((supplier) => ({ value: String(supplier.id), label: supplier.name }))]); watch(() => [props.record, props.category], () => Object.assign(draft, toEventCostDraft(props.record, props.category)), { deep: true }); function submit(){try{localError.value='';emit('save',toEventCostPayload(draft));}catch(error){localError.value=error.message;}}
</script>
<template><section class="mds-mobile-app flex h-[100dvh] min-w-0 flex-col overflow-hidden bg-[var(--mds-bg)]" :style="safeAreaStyle"><MMobileTopBar :title="title" @back="discard=true"><template #actions><MButton variant="link" :disabled="saving" @click="discard=true">Hủy</MButton></template></MMobileTopBar><form class="flex min-h-0 flex-1 flex-col" novalidate @submit.prevent="submit"><div class="min-h-0 flex-1 overflow-y-auto"><div class="mds-mobile-gutter-x space-y-4 py-4"><label><span class="mb-1 block text-[13px] font-medium">Nội dung *</span><MInput v-model="draft.title" :disabled="saving" /></label><label><span class="mb-1 block text-[13px] font-medium">Số tiền (đ)</span><MInput v-model="draft.amount" type="number" min="0" :disabled="saving" /></label><label v-if="draft.category==='sponsor'"><span class="mb-1 block text-[13px] font-medium">Danh vị tài trợ</span><MInput v-model="draft.sponsor_tier" :disabled="saving" /></label><label v-if="draft.category==='organization'"><span class="mb-1 block text-[13px] font-medium">Nhà cung cấp</span><MSelect v-model="draft.supplier_id" :options="supplierOptions" :disabled="saving" /></label><label v-if="draft.category==='media'"><span class="mb-1 block text-[13px] font-medium">Đơn vị báo chí</span><MInput v-model="draft.press_org" :disabled="saving" /></label><label v-if="draft.category==='media'"><span class="mb-1 block text-[13px] font-medium">Phóng viên</span><MInput v-model="draft.journalist_name" :disabled="saving" /></label><label v-if="draft.category==='media'"><span class="mb-1 block text-[13px] font-medium">Link nghiệm thu</span><MInput v-model="draft.article_link" type="url" placeholder="https://…" :disabled="saving" /></label><label v-if="draft.category==='sponsor'"><span class="mb-1 block text-[13px] font-medium">Quyền lợi tài trợ</span><MTextarea v-model="draft.sponsor_benefits" :disabled="saving" /></label><label><span class="mb-1 block text-[13px] font-medium">Ghi chú</span><MTextarea v-model="draft.note" :disabled="saving" /></label><p v-if="error || localError" role="alert" class="rounded-lg bg-[var(--mds-danger-bg)] px-3 py-2 text-[13px] text-[var(--mds-danger)]">{{ error || localError }}</p></div></div><footer class="shrink-0 border-t border-[var(--mds-border-light)] bg-[var(--mds-bg)] px-4 pb-[calc(12px+var(--mds-mobile-safe-bottom))] pt-3"><MButton variant="primary" class="w-full" :loading="saving" :disabled="saving" @click="submit">Lưu dòng chi phí</MButton></footer></form><MDialog v-model="discard" title="Bỏ thay đổi?" type="danger" confirm-text="Bỏ thay đổi" @confirm="emit('cancel')"><p>Dòng chi phí chưa lưu sẽ không được giữ lại.</p></MDialog></section></template>
